<template>
  <main v-if="hasCartItems" class="order-shell">
    <header class="order-intro"><div><p class="order-kicker">Santa's Capybara Atelier</p><h1 class="order-title">Your order</h1><p>A considered selection from the holiday collection.</p></div><div class="order-badge">Illustrative order</div></header>
    <section class="order-layout" aria-label="Order details">
      <div class="order-paper"><div class="paper-head"><span>Atelier dispatch note</span><span class="order-reference">Order ref · {{ orderReference }}</span></div><div class="line-header"><span>Collection piece</span><span>Quantity</span><span>Total</span></div><article v-for="item in cartItems" :key="item.product.id" class="order-line"><div class="item-detail"><img :src="item.product.image" :alt="item.product.name" /><div class="line-product"><router-link :to="`/product/${item.product.id}`">{{ item.product.name }}</router-link><span>{{ formatPrice(item.product.price) }} each</span><button class="remove-link" type="button" :aria-label="`Remove ${item.product.name} from order`" @click="removeFromCart(item)">Remove</button></div></div><div class="quantity-stepper" :aria-label="`Quantity for ${item.product.name}`"><button type="button" :aria-label="`Decrease quantity for ${item.product.name}`" @click="decrementQuantity(item)">−</button><input v-model.number="item.quantity" type="number" min="1" :aria-label="`Quantity for ${item.product.name}`" @change="updateQuantity(item)" /><button type="button" :aria-label="`Increase quantity for ${item.product.name}`" @click="incrementQuantity(item)">+</button></div><strong class="line-total">{{ formatPrice(item.product.price * item.quantity) }}</strong></article><p class="paper-foot">Selected with care · showcase order only</p></div>
      <aside class="order-summary"><p class="summary-label">Order summary</p><div><span>Items</span><span>{{ itemCount }} pieces</span></div><div><span>Subtotal</span><strong>{{ formatPrice(calculateSubtotal()) }}</strong></div><div><span>Order</span><span>Illustrative</span></div><div class="summary-total"><span>Total</span><strong>{{ formatPrice(calculateSubtotal()) }}</strong></div><p class="summary-note">No payment or fulfilment is processed in this conference demo.</p><button class="submit-order" type="button" :disabled="isSubmitting" @click="submitOrder">{{ isSubmitting ? 'Sending order…' : 'Send order' }}</button><button class="continue-button" type="button" @click="continueShopping">Continue browsing</button></aside>
    </section>
  </main>
  <main v-else class="empty-cart"><p>Santa's Capybara Atelier</p><h1>Your cart is waiting for a keepsake.</h1><span>Start with a little holiday warmth from the collection.</span><button type="button" @click="continueShopping">Browse the collection</button></main>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import { useCartStore } from '@/stores'
import { useRouter } from 'vue-router'
import type { CartItem } from '@/types'
const cartStore = useCartStore(); const router = useRouter(); const isSubmitting = ref(false)
const cartItems = computed(() => cartStore.items); const hasCartItems = computed(() => cartItems.value.length > 0); const itemCount = computed(() => cartItems.value.reduce((total, item) => total + item.quantity, 0)); const orderReference = computed(() => `SC-${String(cartItems.value.reduce((total, item) => total + Number(item.product.id) * item.quantity, 0)).padStart(4, '0')}`)
const formatPrice = (price: number): string => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(price)
const calculateSubtotal = (): number => cartItems.value.reduce((total, item) => total + item.product.price * item.quantity, 0)
const updateQuantity = (item: CartItem): void => { if (item.quantity < 1 || Number.isNaN(item.quantity)) item.quantity = 1 }
const incrementQuantity = (item: CartItem): void => { item.quantity++; updateQuantity(item) }; const decrementQuantity = (item: CartItem): void => { item.quantity--; updateQuantity(item) }; const removeFromCart = (item: CartItem): void => { cartStore.removeItem(item.product.id) }; const continueShopping = (): void => { router.push('/') }
const submitOrder = (): void => { if (isSubmitting.value) return; isSubmitting.value = true; const order = { customerId: Math.floor(Math.random() * 10000000000).toString(), items: cartItems.value.map((item) => ({ productId: item.product.id, quantity: item.quantity, price: item.product.price })) }; fetch('/api/orders', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(order) }).then((response) => { if (!response.ok) throw new Error('Order request failed'); cartStore.clear(); alert('Order sent successfully') }).catch(() => { alert('The order could not be sent. Please try again.') }).finally(() => { isSubmitting.value = false }) }
</script>
<style scoped>
