ne-product a{display:block;overflow:hidden;color:var(--text-color);font-weight:800;text-overflow:ellipsis;white-space:nowrap}.line-product span{display:block;margin-top:4px;color:var(--muted-text);font-size:.85rem}.remove-link{min-height:auto;margin-top:9px;padding:0;background:transparent;color:var(--accent-color);box-shadow:none;font-size:.76rem}.quantity-stepper{display:inline-grid;grid-template-columns:32px 42px 32px;justify-self:end;overflow:hidden;border:1px solid #cdb68d;border-radius:8px;background:#fffdf7}.quantity-stepper button{min-height:38px;padding:0;border:0;border-radius:0;background:transparent;color:var(--primary-color);box-shadow:none}.quantity-stepper input{width:42px;border:0;border-right:1px solid #e1d0ad;border-left:1px solid #e1d0ad;background:transparent;text-align:center}.line-total{text-align:right;font-variant-numeric:tabular-nums}.paper-foot{margin:0;padding:16px 22px;border-top:1px dashed #d6c09a;color:var(--muted-text);font-size:.78rem;font-style:italic}.order-summary{padding:24px}.order-summary>div{display:flex;justify-content:space-between;gap:18px;padding:10px 0;color:var(--muted-text);font-size:.92rem}.order-summary strong{color:var(--text-color);font-variant-numeric:tabular-nums}.summary-total{margin-top:8px;padding-top:18px!important;border-top:1px solid #d8c39f;color:var(--text-color)!important;font-size:1.12rem!important;font-weight:800}.summary-note{margin:16px 0 20px;color:var(--muted-text);font-size:.78rem;line-height:1.5}.submit-order,.continue-button{width:100%}.continue-button{margin-top:9px;border-color:#cdb68d;background:transparent;color:var(--primary-color);box-shadow:none}.empty-cart{display:flex;flex-direction:column;align-items:center;max-width:680px;min-height:65vh;justify-content:center;text-align:center}.empty-cart span{max-width:38ch;margin:14px 0 24px;color:var(--muted-text);line-height:1.6}@media(max-width:760px){.order-intro{align-items:start;flex-direction:column}.order-layout{grid-template-columns:1fr}.paper-head{align-items:start;flex-direction:column}.line-header{display:none}.order-line{grid-template-columns:1fr auto;gap:12px;padding:16px}.item-detail{grid-column:1}.quantity-stepper{grid-column:1;justify-self:start}.line-total{grid-column:2;grid-row:1}.order-summary{padding:20px}}
</style>
